using System.Text.Json;
using VisionFramework;
using VisionModules;
string? path=args.FirstOrDefault();if(path is null){var folder=new DirectoryInfo(AppContext.BaseDirectory);while(folder is not null){var candidate=Path.Combine(folder.FullName,"examples","architecture-demo.vmx.json");if(File.Exists(candidate)){path=candidate;break;}folder=folder.Parent;}}if(path is null)throw new Exception("Pass architecture demo solution path.");
var workspace=SolutionStore.OpenWorkspace(path);var registry=new ModuleRegistry();BuiltinModules.RegisterAll(registry);var executor=new SolutionExecutor(registry);int checks=0;
void Check(bool yes,string label){if(!yes)throw new Exception(label);checks++;Console.WriteLine("PASS "+label);}
var result=await executor.RunAsync(workspace,"main");Check(result.Status==SessionStatus.Success&&result.Nodes.Count==5&&result.Nodes.All(n=>n.Status==NodeRunStatus.Success),"saved five-node fan-out solution executes");
Check(result.Nodes.Single(n=>n.NodeId=="components").Outputs["Count"].As<long>()>0,"image to threshold to components pipeline");Check(result.Nodes.Single(n=>n.NodeId=="compare").Outputs["Passed"].As<bool>(),"circle radius reaches typed number comparison");
var procedure=workspace.Document.Procedures[0];ProcedureDocument Change(string id,string key,object value)=>procedure with{Nodes=procedure.Nodes.Select(n=>n.Id!=id?n:n with{Parameters=n.Parameters.Concat(Array.Empty<KeyValuePair<string,JsonElement>>()).ToDictionary(x=>x.Key,x=>x.Value)}).Select(n=>{if(n.Id==id)n.Parameters[key]=JsonSerializer.SerializeToElement(value);return n;}).ToArray()};
var noMatch=Change("circle","CenterX",10000.0);var missing=await new GraphExecutor(registry).RunAsync(noMatch,workspace.BaseDirectory);Check(missing.Nodes.Single(n=>n.NodeId=="circle").Status==NodeRunStatus.NoMatch,"no target differs from runtime error");Check(missing.Nodes.Single(n=>n.NodeId=="compare").Status==NodeRunStatus.Skipped&&missing.Nodes.Single(n=>n.NodeId=="compare").Outputs.Count==0,"missing radius never produces old comparison result");Check(missing.Nodes.Single(n=>n.NodeId=="components").Status==NodeRunStatus.Success,"independent branch still executes");
var broken=Change("source","Path","missing-image.bmp");var failed=await new GraphExecutor(registry).RunAsync(broken,workspace.BaseDirectory);Check(failed.Status==SessionStatus.Failed&&failed.Nodes.Single(n=>n.NodeId=="source").Status==NodeRunStatus.Failed&&failed.Nodes.Where(n=>n.NodeId!="source").All(n=>n.Status==NodeRunStatus.Skipped&&n.Outputs.Count==0),"failed image source blocks both descendants");
var stale=workspace with{Document=workspace.Document with{Resources=workspace.Document.Resources.Select(r=>r with{Sha256=new string('a',64)}).ToArray()}};try{await executor.RunAsync(stale,"main");throw new Exception("Accepted stale resource.");}catch(InvalidDataException){checks++;Console.WriteLine("PASS resource mismatch prevents execution");}
var mismatch=procedure with{Connections=procedure.Connections.Select(c=>c.ToNode=="compare"?c with{FromNode="components",FromPort="Count"}:c).ToArray()};Check(GraphValidator.Validate(mismatch,registry).Issues.Any(i=>i.Code=="PortType"),"integer to number requires explicit conversion");
var rejectedMeasure=await new GraphExecutor(registry).RunAsync(Change("compare","Reference",400.0),workspace.BaseDirectory);Check(rejectedMeasure.Status==SessionStatus.Success&&!rejectedMeasure.Nodes.Single(n=>n.NodeId=="compare").Outputs["Passed"].As<bool>(),"completed execution is distinct from measurement pass");
Console.WriteLine($"{checks} real module graph integration checks passed.");

